CREATE TABLE IF NOT EXISTS "dm_doc" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" varchar(255) NOT NULL,
  "is_public" boolean NOT NULL DEFAULT FALSE,
  "share_code" varchar(32) DEFAULT NULL,
  "view_num" integer DEFAULT 0,
  "view_chapter_num" integer DEFAULT 0,
  "crt_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "crt_user" varchar(32) NOT NULL,
  "crt_name" varchar(255) NOT NULL,
  "crt_host" varchar(255) DEFAULT NULL,
  "upd_time" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "upd_user" varchar(32) DEFAULT NULL,
  "upd_name" varchar(255) DEFAULT NULL,
  "upd_host" varchar(255) DEFAULT NULL,
  "deleted" boolean NOT NULL DEFAULT FALSE,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "dm_doc" IS 'DOC-文档';
COMMENT ON COLUMN "dm_doc"."id" IS 'ID';
COMMENT ON COLUMN "dm_doc"."name" IS '文档名称';
COMMENT ON COLUMN "dm_doc"."is_public" IS '是否公开';
COMMENT ON COLUMN "dm_doc"."share_code" IS '分享码';
COMMENT ON COLUMN "dm_doc"."view_num" IS '访问次数';
COMMENT ON COLUMN "dm_doc"."view_chapter_num" IS '章节总访问次数';
COMMENT ON COLUMN "dm_doc"."crt_time" IS '创建时间';
COMMENT ON COLUMN "dm_doc"."crt_user" IS '创建用户ID';
COMMENT ON COLUMN "dm_doc"."crt_name" IS '创建用户';
COMMENT ON COLUMN "dm_doc"."crt_host" IS '创建IP';
COMMENT ON COLUMN "dm_doc"."upd_time" IS '更新时间';
COMMENT ON COLUMN "dm_doc"."upd_user" IS '更新用户ID';
COMMENT ON COLUMN "dm_doc"."upd_name" IS '更新用户';
COMMENT ON COLUMN "dm_doc"."upd_host" IS '更新IP';
COMMENT ON COLUMN "dm_doc"."deleted" IS '是否删除';

CREATE TABLE IF NOT EXISTS "dm_doc_chapter" (
