COMMENT ON COLUMN "dm_doc_chapter"."crt_user" IS '创建用户ID';
COMMENT ON COLUMN "dm_doc_chapter"."crt_name" IS '创建用户';
COMMENT ON COLUMN "dm_doc_chapter"."crt_host" IS '创建IP';
